UPDATE _fodynest_schema_tmp SET s = s || '{"locale":"it","nx_ui_lang":"it","nx_choice_cards":true,"goNextPageAutomatic":true,"allowCompleteSurveyAutomatic":false,"textUpdateMode":"onTyping","showProgressBar":"off","showQuestionNumbers":"off","questionsOnPageMode":"standard","requiredText":"*","pagePrevText":"Indietro","pageNextText":"Avanti","completeText":"Invia le risposte","nx_paradata":true,"nx_no_client_meta":true,"nx_coarse_device":true,"nx_no_probe":["n2_2","n2_3","n2_4","n2_5"],"pages":[{"name":"intro","elements":[{"type":"html","name":"intro_testo","html":"<p style=\"margin:0 0 12px;line-height:1.55\">Questo questionario fa parte di uno studio su FODYNEST.</p><p style=\"margin:0 0 12px;line-height:1.55\">Lo studio confronta <strong style=\"color:#286181\">che cosa chi ha fatto il gioco vuole trasmettere</strong> con che cosa arriva davvero a chi ci gioca.</p><p style=\"margin:0 0 12px;line-height:1.55\">Non ci sono risposte giuste: ci interessa che cosa pensi tu. Meglio frasi concrete che formule generali.</p><p style=\"margin:0 0 12px;line-height:1.55\"><strong style=\"color:#286181\">Rispondi senza consultarti con le altre persone di FODY e le designer.</strong> Anche le differenze tra le vostre risposte sono un dato.</p><p style=\"margin:0 0 12px;line-height:1.55\">Ci vogliono circa 25-30 minuti. Puoi interrompere e riprendere: le risposte restano salvate su questo dispositivo per 14 giorni.</p><p style=\"margin:0 0 12px;line-height:1.55\">Cosa succede alle risposte:</p><ul style=\"list-style:disc outside;margin:0 0 14px;padding-left:1.3em;line-height:1.55\"><li style=\"margin:0 0 6px\">vengono depositate così come sono nella preregistrazione dello studio su OSF, che a fine studio diventa pubblica;</li><li style=\"margin:0 0 6px\">possono essere citate nel paper;</li><li style=\"margin:0 0 6px\"><strong style=\"color:#286181\">non sono anonime</strong>, perché il gioco e chi lo ha fatto sono noti;</li><li style=\"margin:0 0 6px\">la piattaforma registra anche il tempo passato su ogni pagina e il tipo di dispositivo (telefono, tablet o computer).</li></ul><p style=\"margin:0 0 12px;line-height:1.55\">Partecipare è libero e puoi ritirarti quando vuoi.</p><p style=\"margin:0 0 12px;line-height:1.55\">Ricerca di NexLudica APS. Responsabile: Vittorio Guerrieri.</p>"},{"type":"boolean","name":"consent_partecipazione","renderAs":"checkbox","titleLocation":"hidden","title":"Ho letto queste informazioni e accetto di partecipare e che le mie risposte siano usate come descritto.","label":"Ho letto queste informazioni e accetto di partecipare e che le mie risposte siano usate come descritto.","isRequired":true,"requiredErrorText":"Per andare avanti spunta la casella."}],"title":"Prima di iniziare"},{"name":"p_chi","elements":[{"type":"text","name":"chi_compila","title":"Il tuo nome e il tuo ruolo in FODY","isRequired":true,"requiredErrorText":"Questa risposta serve per andare avanti.","autocomplete":"off"}],"title":"Chi compila"},{"name":"p_n1","elements":[{"type":"comment","name":"n1","title":"Immagina una persona che ha appena finito una partita a FODYNEST. Se dovesse dire in una frase che cosa le ha lasciato il gioco, quale frase vorresti sentire?","rows":5,"autoGrow":true,"allowResize":false}],"title":"Che cosa vuoi trasmettere"},{"name":"p_n2","elements":[{"type":"panel","name":"n2_panel","title":"Elenca fino a cinque cose (idee, conoscenze, atteggiamenti) che vorresti arrivassero a chi gioca, in ordine di importanza.","description":"Una per casella: appena ne scrivi una, compare la casella per la successiva.","elements":[{"type":"comment","name":"n2_1","title":"Prima cosa","rows":2,"autoGrow":true,"allowResize":false},{"type":"comment","name":"n2_2","title":"Seconda cosa","rows":2,"autoGrow":true,"allowResize":false,"visibleIf":"{n2_1} notempty"},{"type":"comment","name":"n2_3","title":"Terza cosa","rows":2,"autoGrow":true,"allowResize":false,"visibleIf":"{n2_2} notempty"},{"type":"comment","name":"n2_4","title":"Quarta cosa","rows":2,"autoGrow":true,"allowResize":false,"visibleIf":"{n2_3} notempty"},{"type":"comment","name":"n2_5","title":"Quinta cosa","rows":2,"autoGrow":true,"allowResize":false,"visibleIf":"{n2_4} notempty"}]}]},{"name":"p_n3","elements":[{"type":"comment","name":"n3","title":"Che idea di impresa sociale nel tessile, e che idea di FODY, vorresti che si facesse chi gioca?","rows":5,"autoGrow":true,"allowResize":false}]},{"name":"p_n4","elements":[{"type":"comment","name":"n4","title":"Che rapporto tra guadagnare e fare scelte etiche vorresti che chi gioca percepisse?","rows":5,"autoGrow":true,"allowResize":false}]},{"name":"p_n5","elements":[{"type":"comment","name":"n5","title":"Che cosa vorresti che chi gioca provasse durante la partita?","rows":5,"autoGrow":true,"allowResize":false}]},{"name":"p_n6","elements":[{"type":"comment","name":"n6","title":"Dopo la partita, che cosa vorresti che chi gioca pensasse o facesse di diverso nella vita di tutti i giorni?","rows":5,"autoGrow":true,"allowResize":false}]},{"name":"p_n7","elements":[{"type":"comment","name":"n7","title":"C''è qualcosa che non vorresti che chi gioca concludesse dal gioco?","rows":5,"autoGrow":true,"allowResize":false}]},{"name":"p_c1","elements":[{"type":"comment","name":"c1","title":"Descrivi FODY in tre frasi, come vorresti che la raccontasse chi ha giocato.","rows":5,"autoGrow":true,"allowResize":false}],"title":"FODY nel gioco"},{"name":"p_c2","elements":[{"type":"comment","name":"c2","title":"Quali pratiche di FODY dovrebbero essere riconoscibili nel gioco? Per ciascuna: dove la ritrovi nel gioco, se c''è?","rows":5,"autoGrow":true,"allowResize":false}]},{"name":"p_c3","elements":[{"type":"comment","name":"c3","title":"C''è qualcosa nel gioco che rappresenta FODY o il settore tessile in modo impreciso?","rows":5,"autoGrow":true,"allowResize":false}]},{"name":"p_c4","elements":[{"type":"comment","name":"c4","title":"A chi vorresti far giocare FODYNEST, e in quali occasioni?","rows":5,"autoGro